361	/// One registered package's identity and on-disk location, adapted from a
362	/// real `Workspace` by `crate::commands::matrix::matrix` (or built directly
363	/// by tests).
364	pub(crate) struct MatrixPackageInput {
365	    pub id: PackageId,
366	    /// Absolute path to the package's directory (used for manifest reads).
367	    pub dir_abs: PathBuf,
368	    /// Workspace-root-relative path string, stored verbatim on each
369	    /// PlatformTarget.package_dir.
370	    pub dir_rel: String,
371	    pub name: String,
372	}
